using SparkFlow.Server.Application.Services; using SparkFlow.Server.Domain.Entities; namespace SparkFlow.Server.Application.Features.Workers.RegisterWorker; public sealed class RegisterWorkerHandler { private readonly WorkerService _service; public RegisterWorkerHandler(WorkerService service){_service=service;} public Task<WorkerNode> Handle(RegisterWorkerCommand command, CancellationToken cancellationToken=default)=>_service.RegisterAsync(command.Name, command.MachineId, command.Version, command.MaxConcurrentSessions, cancellationToken);}
